const f = $input.first().json;
const docId = String(f.document_id || '').trim();
if (!/^[A-Za-z0-9_-]{1,100}$/.test(docId)) throw new Error('document_id khong hop le, nhan duoc: ' + JSON.stringify(docId));
const action = String(f.action || '').trim();
if (!['rollback', 'revoke'].includes(action)) throw new Error('action khong hop le: ' + JSON.stringify(action));
if ([].concat(f.confirmed || []).length === 0) throw new Error('Chua xac nhan thao tac');
const approver = String(f.approver || '').trim().slice(0, 100);
if (!approver) throw new Error('Thieu nguoi duyet');
return [{ json: { document_id: docId, action, approver } }];

