const body = $('Webhook').first().json.body || {};

// Xử lý phạm vi kiểm thử (Testing / Draft vs Production / Approved):
// - Nếu là workflow hr-policy-preview (QA): mặc định hỗ trợ kiểm thử tài liệu testing (trừ khi cố tình chọn production)
// - Nếu là workflow hr-policy-chat: kiểm tra cờ include_testing do auth-service xác thực truyền sang
const test = body.include_testing !== false && body.scope !== 'production';

const role = ['new_hire', 'employee', 'manager', 'hr', 'admin', 'super_admin'].includes(body.role)
  ? body.role
  : null;

// Xác thực & Phân giải Company/Branch
const compUpper = String(body.company_id || '').trim().toUpperCase();
const branchRaw = String(body.branch || '').trim().toLowerCase();
const userId = String(body.user_id || '').trim().toUpperCase();

let verifiedBranch = null;
if (compUpper === 'STL' || branchRaw === 'sotrans_logistics' || branchRaw === 'stl' || userId.startsWith('STL')) {
  verifiedBranch = 'sotrans_logistics';
} else if (compUpper === 'VTX' || branchRaw === 'vietranstimex' || branchRaw === 'vtx' || userId.startsWith('VTX')) {
  verifiedBranch = 'vietranstimex';
} else if (compUpper === 'SWC' || branchRaw === 'sowatco' || branchRaw === 'swc' || userId.startsWith('SWC')) {
  verifiedBranch = 'sowatco';
} else if (compUpper === 'ALL' || branchRaw === 'all' || userId === 'SUPER_ADMIN' || userId === 'ADMIN_GLOBAL') {
  verifiedBranch = 'all';
} else if (['sotrans_logistics', 'vietranstimex', 'sowatco'].includes(branchRaw)) {
  verifiedBranch = branchRaw;
} else {
  verifiedBranch = 'all';
}

// Khi verifiedBranch là 'all' (Super Admin hoặc xem toàn tập đoàn):
// Cho phép truy xuất toàn bộ văn bản của tất cả các công ty thành viên.
// Khi thuộc một công ty cụ thể (ví dụ sowatco): chỉ cho phép 'all' (văn bản chung) và 'sowatco'.
const ALL_KNOWN_BRANCHES = ['all', 'sotrans_logistics', 'vietranstimex', 'sowatco'];
const branches = (verifiedBranch === 'all')
  ? ALL_KNOWN_BRANCHES
  : ['all', verifiedBranch];

const message = String(body.message || '')
  .normalize('NFC')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 500);

if (message.length < 2) throw new Error('Thiếu trường message');

// Lấy kết quả Rewrite hoặc fallback về message gốc nếu Rewrite lỗi/rỗng
const rw = ($json.candidates?.[0]?.content?.parts || [])
  .map(p => p.text || '')
  .join('')
  .trim()
  .replace(/^['“”"']+|['“”"']+$/g, '');

const q = (rw.length >= 2 ? rw : message)
  .normalize('NFC')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 500);

const d = new Date(Date.now() + 7 * 3600 * 1000);
const today = Number(d.toISOString().slice(0, 10).replace(/-/g, ''));

// Keyword text dùng cả câu gốc và câu rewrite
const searchText = `${message} ${q}`;
const un = searchText
  .normalize('NFD')
  .replace(/\p{M}/gu, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'D')
  .toLowerCase();

const STOP = new Set([
  'la','cua','bao','nhieu','thi','co','duoc','gi','khong','toi','minh',
  'nhu','the','nao','va','cho','voi','khi','nay','cac','mot','se','bi',
  'hay','em','anh','chi','ban','o','ve','theo','cho'
]);

const baseTokens = [...new Set(un.match(/[a-z0-9]+/g) || [])]
  .filter(t => !STOP.has(t) && t.length > 1)
  .slice(0, 30);

// Từ điển đồng nghĩa chuyên ngành Nhân sự, Pháp lý, Vận tải, Quy chế doanh nghiệp
const SYN = {
  muon: ['muon', 'tre', 'dilammuon', 'ditre', 'chuyencan'],
  tre: ['tre', 'muon', 'ditre', 'dilammuon', 'chuyencan'],
  ditre: ['ditre', 'dilammuon', 'tre', 'muon'],
  dilammuon: ['dilammuon', 'ditre', 'muon', 'tre'],
  phep: ['phep', 'nghi', 'phepnam', 'nghiphep', 'chedo'],
  nghi: ['nghi', 'phep', 'nghiphep', 'nghibu', 'khongluong'],
  phepnam: ['phepnam', 'phep', 'nghi', 'hangnam'],
  phucloi: ['phucloi', 'phuc', 'loi', 'chedo', 'daingo', 'khenthuong'],
  phuc: ['phuc', 'phucloi', 'loi'],
  loi: ['loi', 'phucloi', 'phuc'],
  luong: ['luong', 'thuong', 'thunhap', 'phucap'],
  thuong: ['thuong', 'luong', 'khenthuong', 'phucloi'],
  khenthuong: ['khenthuong', 'thuong', 'phucloi', 'thiduoc'],
  lamthem: ['lamthem', 'overtime', 'ot', 'tangca', 'ngaynghi'],
  overtime: ['overtime', 'lamthem', 'ot', 'tangca'],
  ot: ['ot', 'overtime', 'lamthem', 'tangca'],
  baohiem: ['baohiem', 'bhxh', 'bhyt', 'bhtn', 'suckhoe', 'toandien', 'cargo', 'tpl', 'cpm'],
  bhxh: ['bhxh', 'baohiem', 'xahoi'],
  bhyt: ['bhyt', 'baohiem', 'yte'],
  bhtn: ['bhtn', 'baohiem', 'thatnghiep'],
  thaisan: ['thaisan', 'nghithaisan', 'chedo', 'sinhcon'],
  omdau: ['omdau', 'nghiom', 'chedo', 'benhtat'],
  kyluat: ['kyluat', 'vipham', 'phat', 'chetai', 'khientrach', 'sathai'],
  phat: ['phat', 'kyluat', 'tru', 'chetai'],
  vipham: ['vipham', 'kyluat', 'phat', 'chetai'],
  chetai: ['chetai', 'kyluat', 'phat', 'xuly'],
  antoan: ['antoan', 'baoho', 'ppe', 'tnld', 'laodong', 'qhse', 'swa'],
  baoho: ['baoho', 'ppe', 'trangbi', 'trangphuc'],
  ppe: ['ppe', 'baoho', 'trangbi'],
  giay: ['giay', 'dep', 'baoho', 'thep', 'chongdinh'],
  mu: ['mu', 'non', 'baoho'],
  non: ['non', 'mu', 'baoho'],
  sieutruong: ['sieutruong', 'sieutrong', 'spmt', 'duan', 'vanchuyen', '32'],
  sieutrong: ['sieutrong', 'sieutruong', 'spmt', 'duan', 'vanchuyen', '32'],
  spmt: ['spmt', 'thietbi', 'vanchuyen', 'nang', 'ro-mooc'],
  cau: ['cau', 'gantry', 'rtg', 'nang'],
  gantry: ['gantry', 'cau', 'rtg'],
  rtg: ['rtg', 'cau', 'gantry'],
  xenang: ['xenang', 'forklift', 'nang'],
  forklift: ['forklift', 'xenang'],
  cang: ['cang', 'vict', 'kho', 'bai', 'haiphong', 'saigon'],
  vict: ['vict', 'cang', 'cont'],
  hientruong: ['hientruong', 'dacthu', 'congtac', 'chiendich', 'khaosat'],
  congtac: ['congtac', 'congtacphi', 'hientruong', 'phucap'],
  giayphep: ['giayphep', 'luuhanh', 'dieuphoi', 'giaothong'],
  luuhanh: ['luuhanh', 'giayphep', 'giaothong'],
  thutuc: ['thutuc', 'hoso', 'quytrinh', 'cacbuoc', 'trinhtu', 'giayto'],
  hoso: ['hoso', 'thutuc', 'giayto', 'chungtu', 'bienban'],
  quytrinh: ['quytrinh', 'thutuc', 'cacbuoc', 'trinhtu', 'huongdan'],
  trachnhiem: ['trachnhiem', 'nhiemvu', 'raci', 'phancong', 'thamquyen'],
  raci: ['raci', 'trachnhiem', 'matrix', 'phancong'],
  thamquyen: ['thamquyen', 'pheduyet', 'quyetdinh', 'trachnhiem'],
  dieukien: ['dieukien', 'tieuchuan', 'doituong', 'apdung', 'quydinh'],
  ngoaile: ['ngoaile', 'loaitru', 'khongapdung', 'trutruonghop', 'dacbiet'],
  thoihan: ['thoihan', 'thoidiem', 'hanchot', 'deadline', 'thoigian', 'ngay'],
  khaosat: ['khaosat', 'tuyenduong', 'hientruong', 'survey'],
  checklist: ['checklist', 'kiemtra', 'danhmuc', 'antoan'],
  pccc: ['pccc', 'phongchay', 'chuachay'],
  phongchay: ['phongchay', 'pccc'],
  chuachay: ['chuachay', 'pccc']
};

const expanded = [];
for (const t of baseTokens) {
  for (const x of (SYN[t] || [t])) expanded.push(x);
}
const tokens = [...new Set(expanded)].slice(0, 48);

const statuses = test ? ['active', 'testing'] : ['active'];
const roles = ['all', role].filter(Boolean);

return [{ json: {
  message,
  original_query: message,
  q_text: q,
  rewritten: rw || null,
  keyword_text: searchText,
  today,
  user_id: userId,
  user_role: role || 'chua xác định',
  user_branch: verifiedBranch,
  tsq: tokens.join(' | ') || 'khongcogi',
  is_testing_scope: test,
  statuses,
  status_list: statuses.map(s => `'${s}'`).join(','),
  roles,
  branches,
  roles_sql: '{' + roles.join(',') + '}',
  branches_sql: '{' + branches.join(',') + '}'
} }];

