}
return out;

const batches = $('Make batches').all();
const m = $('Join').first().json;
const eff = Number(m.effective_date.replace(/-/g, ''));
const points = [];
$input.all().forEach((resp, i) => {
  const ids = batches[i].json.ids;
  const embs = resp.json.embeddings || [];
  if (embs.length !== ids.length) throw new Error(`Lô ${i}: nhận ${embs.length} vector cho ${ids.length} chunk`);
  ids.forEach((id, k) => {
    const v = embs[k].values;
    if (v.length !== 768) throw new Error('Sai số chiều vector: ' + v.length);
    points.push({ id, vector: v, payload: {
      chunk_id: id, doc_version_id: m.doc_version_id, document_id: m.document_id, version: m.version,
