const p = $('Prep').first().json;
const v = $input.first()?.json?.embedding?.values;
const hasValidVector = Array.isArray(v) && v.length === 768;

const mustFilters = [
  { key: 'status', match: { any: p.statuses } },
  { key: 'role_access', match: { any: p.roles } },
  { key: 'branch_scope', match: { any: p.branches } }
];

// Nếu không phải chế độ kiểm thử thì lọc chặt ngày hiệu lực
if (!p.is_testing_scope) {
  mustFilters.push({ key: 'effective_int', range: { lte: p.today } });
  mustFilters.push({ key: 'expiry_int', range: { gte: p.today } });
}

if (!hasValidVector) {
  // Vector không khả dụng (API sự cố hoặc fallback): gửi query rỗng để Qdrant không văng lỗi
  return [{ json: { body: { filter: { must: mustFilters }, limit: 0, with_payload: true }, has_vector: false } }];
}

return [{ json: { body: { vector: v, limit: 20, with_payload: true, filter: { must: mustFilters } }, has_vector: true } }];

const dense = ($('Qdrant Search').first()?.json?.result) || [];
const kw = ($('PG Keyword').all() || []).map(i => i.json).filter(r => r && r.chunk_id);
const K = 60;
const score = {};

// 1. Dynamic Weighting theo chất lượng dense vector
const topDenseSim = dense.length ? Number(dense[0]?.score || 0) : 0;
const kwWeight = topDenseSim < 0.70 ? 1.6 : 1.0;
const denseWeight = 1.0;

for (let i = 0; i < dense.length; i++) {
  const id = String(dense[i]?.payload?.chunk_id || '').toLowerCase();
  if (!/^[0-9a-f-]{36}$/.test(id)) continue;
  score[id] = (score[id] || 0) + (denseWeight / (K + i + 1));
}

for (let i = 0; i < kw.length; i++) {
  const id = String(kw[i]?.chunk_id || '').toLowerCase();
  if (!/^[0-9a-f-]{36}$/.test(id)) continue;
  score[id] = (score[id] || 0) + (kwWeight / (K + i + 1));
}

// 2. Bảo toàn tuyệt đối cho Top 3 BM25 Keyword Matches từ PostgreSQL
const guaranteedKwIds = kw.slice(0, 3)
  .map(k => String(k.chunk_id).toLowerCase())
  .filter(id => /^[0-9a-f-]{36}$/.test(id));

const sortedIds = Object.entries(score)
  .sort((a, b) => b[1] - a[1])
  .map(e => e[0])
  .filter(x => /^[0-9a-f-]{36}$/.test(x));

// Kết hợp: ưu tiên các mục có điểm RRF cao nhất, đồng thời bảo toàn chắc chắn các top keyword
const combinedSet = new Set();
for (const id of guaranteedKwIds) combinedSet.add(id);
for (const id of sortedIds) {
  combinedSet.add(id);
  if (combinedSet.size >= 14) break;
}

const ids = [...combinedSet];
const pass = ids.length > 0;
const best = topDenseSim > 0 ? topDenseSim : (kw.length > 0 ? 0.75 : 0);

return [{ json: {
  ids,
  ids_sql: '{' + ids.join(',') + '}',
  best_sim: best,
  dense_count: dense.length,
  keyword_count: kw.length,
  rrf_count: ids.length,
  pass
} }];

