    .map(i => i.json)
    .filter(r => r && r.chunk_id)
    .map(r => [String(r.chunk_id).toLowerCase(), r])
);

const map = {};
const parts = [];

order.filter(id => rows[id]).forEach((id, k) => {
  const r = rows[id];
  const cid = 'C' + (k + 1);
  map[cid] = r;
  const safeTitle = String(r.title || '').replace(/[<>]/g, '');
  const safeNumber = String(r.doc_number || 's/n').replace(/[<>]/g, '');
  const safePath = String(r.section_path || '').replace(/[<>]/g, '');
  const statusStr = r.status === 'testing' ? 'trang_thai="testing (bản kiểm thử/dự thảo)"' : 'trang_thai="active (chính thức)"';
  parts.push(
    `<tai_lieu id="${cid}" file="${safeTitle}" so_vb="${safeNumber}" dieu_muc="${safePath}" hieu_luc_tu="${r.effective_date}" phien_ban="v${r.version}" ${statusStr}>${String(r.content || '')}</tai_lieu>`
  );
});

const s = String(p.today);
const vars = {
  company_name: COMPANY,
  current_date: `${s.slice(6,8)}/${s.slice(4,6)}/${s.slice(0,4)}`,
  user_role: p.user_role,
  user_branch: p.user_branch,
  hr_contact: HR_CONTACT,
  retrieved_context: parts.length ? parts.join('\n\n') : '(Không có đoạn văn bản nào)'
};

const system = PROMPT.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? '');

return [{ json: {
  map,
  n: parts.length,
  hr_contact: HR_CONTACT,
  gemini_body: {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: p.message }] }],
    generationConfig: {
      temperature: 0,
      maxOutputTokens: 2048,
      responseMimeType: 'application/json'
    }
  }
} }];

const ctx = $('Build_Context').first().json;
const raw = ($json.candidates?.[0]?.content?.parts || [])
  .map(p => p.text || '')
  .join('')
  .trim();

let r = null;
try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) r = JSON.parse(raw.slice(start, end + 1));
} catch (e) {}

const normalize = (s) => String(s ?? '')
  .normalize('NFD')
  .replace(/\p{M}/gu, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'D')
  .toLowerCase()
  .replace(/\*+/g, '')
  .replace(/[^\p{L}\p{N}]+/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const stripAllowedPrefix = (s) => String(s ?? '')
  .replace(/^\s*(theo\s+tai\s+lieu\s*:?)\s*/i, '')
  .replace(/^\s*(quy\s+dinh\s+ghi\s+nhan\s*:?)\s*/i, '')
  .replace(/^\s*(can\s+cu\s+theo\s*:?)\s*/i, '')
  .replace(/^\s*(\d+[\.\)]|[a-zA-Z][\.\)]|[-•*+#]+)\s*/, '')
  .trim();

const NO = `Hiện tại tài liệu nội bộ mình được cung cấp chưa có thông tin về nội dung bạn hỏi. Bạn vui lòng liên hệ trực tiếp phòng Nhân sự: ${ctx.hr_contact}.`;

const errors = [];
const validCitations = [];
const modelAnswerable = r?.answerable === true;

if (!r || typeof r.answer !== 'string' || !Array.isArray(r.citations)) {
  errors.push('invalid_json_or_schema');
}

if (r && r.answerable === false) {
  r.citations = [];
  if (typeof r.answer !== 'string' || !r.answer.trim()) r.answer = NO;
}

if (modelAnswerable) {
  for (const c of r.citations) {
    const cid = String(c?.chunk_id || '').trim();
    const chunk = ctx.map?.[cid];
    const quote = String(c?.evidence_quote || '').trim();

    if (!chunk) {
      errors.push(`unknown_chunk:${cid}`);
      continue;
    }

    if (!quote) {
      errors.push(`empty_evidence:${cid}`);
      continue;
    }

    const contentN = normalize(chunk.content);
    const quoteN = normalize(quote);

    let quoteMatched = quoteN && contentN.includes(quoteN);
    if (!quoteMatched && quoteN) {
      const qWords = quoteN.split(/\s+/).filter(w => w.length >= 2);
      if (qWords.length >= 3) {
        for (let qi = 0; qi <= qWords.length - 3; qi++) {
          const sub = qWords.slice(qi, qi + 3).join(' ');
          if (contentN.includes(sub)) {
            quoteMatched = true;
            break;
          }
        }
      } else if (qWords.length >= 1) {
        quoteMatched = qWords.some(w => w.length >= 4 && contentN.includes(w));
      }
    }

    if (!quoteMatched) {
      errors.push(`quote_not_found:${cid}`);
      continue; // Skip invalid citation but DO NOT fail entire response if others are valid
    }

    validCitations.push({ chunk_id: cid, evidence_quote: quote });
  }
}

if (r) r.citations = validCitations;

// Grounding check across answer lines
if (modelAnswerable && validCitations.length > 0 && typeof r.answer === 'string') {
  const answerLines = r.answer
    .split(/\n+/)
    .map(stripAllowedPrefix)
    .map(s => s.trim())
    .filter(Boolean);

  const sourceTexts = validCitations
    .map(c => ctx.map?.[c.chunk_id]?.content)
    .filter(Boolean)
    .map(normalize);

  let groundedLines = 0;
  let factualLines = 0;

  for (let idx = 0; idx < answerLines.length; idx++) {
    const line = answerLines[idx];
    const nline = normalize(line);
    if (!nline || nline.length < 4) continue;

    if (/^(theo tai lieu|quy dinh|nguon|thong tin trong tai lieu|cu the|chi tiet|luu y|noi dung|tom tat|can cu|nhu sau)$/.test(nline)) continue;
    if (idx === 0 && /(nhu sau|bao gom|cac noi dung|quy dinh|chi tiet|sau day):?$/.test(nline)) continue;
    if (/(lien he|phong nhan su|thac mac|ho tro)/.test(nline)) continue;

    factualLines++;
    let directMatch = sourceTexts.some(src => src.includes(nline));
    if (!directMatch && nline.length >= 6) {
      const words = nline.split(/\s+/).filter(w => w.length >= 2);
      if (words.length >= 3) {
        for (let wi = 0; wi <= words.length - 3; wi++) {
          const sub = words.slice(wi, wi + 3).join(' ');
          if (sourceTexts.some(src => src.includes(sub))) {
            directMatch = true;
            break;
          }
        }
      } else if (words.length >= 1) {
        const sub = words.join(' ');
        if (sourceTexts.some(src => src.includes(sub))) {
          directMatch = true;
        }
      }
    }

    if (directMatch) {
      groundedLines++;
    }
  }

  const passRatio = factualLines <= 2 ? (groundedLines >= 1) : (groundedLines / factualLines >= 0.4);
  if (factualLines > 0 && !passRatio) {
    errors.push('answer_contains_unsupported_text');
  }
}

// Validator ONLY blocks if model claimed answerable but NO valid citation matched chunk content,
// OR if answer contains unsupported text. It does NOT block if 1 out of multiple citations had a typo.
const validatorBlocked = modelAnswerable && (
  validCitations.length === 0 ||
  errors.includes('answer_contains_unsupported_text')
);

if (!modelAnswerable) {
  r = {
    answerable: false,
    answer: NO,
    citations: [],
    missing_info: r?.missing_info || 'Tài liệu truy xuất được chưa đủ căn cứ để trả lời.'
  };
} else if (validatorBlocked) {
  r = {
    answerable: false,
    answer: NO,
    citations: [],
    missing_info: 'Câu trả lời không vượt qua kiểm tra căn cứ trích dẫn (grounding/citation).'
  };
} else {
  r.answerable = true;
  r.citations = validCitations;
  r.missing_info = '';
}

// Nhóm nguồn trích dẫn
const docGroups = new Map();
for (const c of (r.citations || [])) {
  const s = ctx.map?.[c.chunk_id];
  if (!s) continue;
  const docKey = s.doc_version_id || s.document_id || `${s.title}:::${s.doc_number || ''}`;
  if (!docGroups.has(docKey)) {
    docGroups.set(docKey, {
      title: s.title || 'Văn bản nội bộ',
      doc_number: s.doc_number || '',
      version: s.version || 1,
      effective_date: s.effective_date || '',
      status: s.status || 'active',
      sections: []
    });
  }
  const group = docGroups.get(docKey);
  const path = String(s.section_path || '').trim();
  if (path && !group.sections.includes(path)) group.sections.push(path);
}

const sources = Array.from(docGroups.values()).map(g => {
  const parts = [];
  if (g.doc_number && g.doc_number !== 's/n') parts.push(g.doc_number);
  parts.push(`v${g.version}`);
  if (g.effective_date) parts.push(`hiệu lực từ ${g.effective_date}`);
  if (g.status === 'testing') parts.push('bản kiểm thử/dự thảo');
  const meta = parts.length ? ` (${parts.join(', ')})` : '';
  const secStr = g.sections.length ? ` – Căn cứ: ${g.sections.join('; ')}` : '';
  return `• **${g.title}**${meta}${secStr}`;
});

let formattedReply = r.answer;
if (r.answerable && sources.length > 0) {
  formattedReply += '\n\n**Nguồn:**\n' + sources.join('\n');
}

const flatSources = (r.citations || []).map(c => {
  const chunk = ctx.map?.[c.chunk_id] || {};
  return {
    id: c.chunk_id,
    title: chunk.title || '',
    doc_number: chunk.doc_number || '',
    section_path: chunk.section_path || '',
    effective_date: chunk.effective_date || '',
    version: chunk.version || 1,
    status: chunk.status || 'active',
    doc_version_id: chunk.doc_version_id || null,
    evidence_quote: c.evidence_quote || '',
    content: chunk.content || ''
  };
});

const docVersionIds = [...new Set(flatSources.map(s => s.doc_version_id).filter(Boolean))];
const bestSim = $('RRF').first()?.json?.best_sim || 0;

return [{ json: {
  raw,
  reply: formattedReply,
  answerable: r.answerable,
  sources: flatSources,
  doc_versions: docVersionIds,
  best_sim: bestSim,
  errors,
  missing_info: r.missing_info || '',
  validator_blocked: validatorBlocked,
  debug: {
    rewritten: $('Prep').first()?.json?.rewritten || null,
    original_query: $('Prep').first()?.json?.message || '',
    keyword_text: $('Prep').first()?.json?.keyword_text || '',
    best_sim: bestSim,
    dense_count: $('RRF').first()?.json?.dense_count || 0,
    keyword_count: $('RRF').first()?.json?.keyword_count || 0,
    rrf_count: $('RRF').first()?.json?.rrf_count || 0,
    n_chunks: ctx.n || 0,
    validator_blocked: validatorBlocked,
    validation_errors: errors,
    valid_citations: validCitations,
    raw
  }
} }];

